// FUNCTION: BFME2 0x0049FF50 size=40 name=?startProneEffects@ProneUpdate@@IAEXXZ evidence=N:ledger
void ProneUpdate::startProneEffects()
{
	Object *object = getObject();
	object->setModelConditionState((ModelConditionFlagType)MODELCONDITION_PRONE);
	object->setStatus((ObjectStatusTypes)OBJECT_STATUS_NO_ATTACK, true);
}

// FUNCTION: BFME2 0x0049FF78 size=40 name=?stopProneEffects@ProneUpdate@@IAEXXZ evidence=N:ledger
void ProneUpdate::stopProneEffects()
{
	Object *object = getObject();
	object->clearModelConditionState((ModelConditionFlagType)MODELCONDITION_PRONE);
	object->setStatus((ObjectStatusTypes)OBJECT_STATUS_NO_ATTACK, false);
}

// FUNCTION: BFME2 0x0049FFA0 size=25 name=?update@ProneUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger
UpdateSleepTime ProneUpdate::update()
{
	if (m_proneFrames > 0)
	{
		m_proneFrames--;
		if (m_proneFrames == 0)
			stopProneEffects();
	}
	return UPDATE_SLEEP_NONE;
}

// FUNCTION: BFME2 0x0049FFB9 size=62 name=?goProne@ProneUpdate@@QAEXPBVDamageInfo@@@Z evidence=N:ledger
void ProneUpdate::goProne(const DamageInfo *damageInfo)
{
	Bool wasProne = (m_proneFrames > 0);
	Int damageTaken = (Int)damageInfo->out.m_actualDamageDealt;
	m_proneFrames += damageTaken * getProneUpdateModuleData()->m_damageToFramesRatio;
	if (!wasProne && (m_proneFrames > 0))
		startProneEffects();
}
